using System;using System.IO;using System.Windows.Forms;
namespace SargasPC {
 public sealed class ServiceHeartbeat {public int Schema=1,Version;public string[] ScanRoots,RealtimeRoots;public long ScanStarted,ScanFinished;public bool ScanRequested;public int ManualAccepted,ManualCompleted;public long ManualFinishedAt;public bool ManualPending,ManualRunning,ManualControlReady;public string ManualResult;public bool EngineReady,DatabaseReady;public long DatabaseUpdatedAt,DatabaseProbeAt;public bool RealtimeReady,RealtimeCoverageLost,RealtimeBulkChangeAlert;public int RealtimeActiveRoots,RealtimePending,RealtimeDropped,RealtimeScanned,RealtimeUnverified,RealtimeBulkChangeBursts,RealtimeBulkChangeDistinctPaths;public long RealtimeLastEventAt,RealtimeBulkChangeAlertAt;public int CacheHits;public long At,LastProgress;public string RunId,State;public int DirectoryChecks,Findings,Unverified,Pending,RecordedCases;
  public static ServiceHeartbeat Read(string path){FolderMonitor.NoLinks(path);using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read|FileShare.Delete))return Data.Json().Deserialize<ServiceHeartbeat>(System.Text.Encoding.UTF8.GetString(Data.Bounded(input,8192,null)));}
  public static bool Fresh(ServiceHeartbeat s,long now){return s!=null&&s.Schema==1&&s.Version>0&&s.RunId!=null&&s.RunId.Length==32&&s.LastProgress>=0&&s.LastProgress<=now&&s.At>0&&s.At<=now&&now-s.At<TimeSpan.FromSeconds(90).Ticks&&s.State!=null&&s.State.Length<=80&&s.DirectoryChecks>=0&&s.Findings>=0&&s.Unverified>=0&&s.Pending>=0&&s.RecordedCases>=0&&s.CacheHits>=0&&s.DatabaseUpdatedAt>=0&&s.DatabaseUpdatedAt<=now&&s.DatabaseProbeAt>=0&&s.DatabaseProbeAt<=now&&(!s.DatabaseReady||s.DatabaseProbeAt>0)&&s.RealtimeActiveRoots>=0&&s.RealtimePending>=0&&s.RealtimeDropped>=0&&s.RealtimeScanned>=0&&s.RealtimeUnverified>=0&&s.RealtimeLastEventAt>=0&&s.RealtimeLastEventAt<=now&&s.RealtimeBulkChangeBursts>=0&&s.RealtimeBulkChangeBursts<=1000000&&s.RealtimeBulkChangeDistinctPaths>=0&&s.RealtimeBulkChangeDistinctPaths<=4096&&s.RealtimeBulkChangeAlertAt>=0&&s.RealtimeBulkChangeAlertAt<=now&&(!s.RealtimeBulkChangeAlert||(s.RealtimeBulkChangeAlertAt>0&&s.RealtimeBulkChangeBursts>0&&s.RealtimeBulkChangeDistinctPaths>0))&&((s.RealtimeBulkChangeAlertAt==0)==(s.RealtimeBulkChangeBursts==0))&&(s.ScanStarted>=0&&s.ScanStarted<=now&&s.ScanFinished>=0&&s.ScanFinished<=now)&&(s.ScanRoots==null||(s.ScanRoots.Length<=16&&System.Linq.Enumerable.All(s.ScanRoots,x=>x!=null&&x.Length<=512)))&&(s.RealtimeRoots==null||(s.RealtimeRoots.Length<=16&&System.Linq.Enumerable.All(s.RealtimeRoots,x=>x!=null&&x.Length<=512)))&&s.ManualAccepted>=0&&s.ManualCompleted>=0&&s.ManualCompleted<=s.ManualAccepted&&s.ManualFinishedAt>=0&&s.ManualFinishedAt<=now;}
 }
 public sealed partial class Window {
  private int lastServiceCases=-1;private long lastServiceNotice,lastServiceBulkNoticeAt;private string lastServiceRun="";
  private void ServiceStatusTick(){string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SARGONService","Public","status.json");if(!File.Exists(path))return;long now=DateTime.UtcNow.Ticks;try{FolderMonitor.NoLinks(path);var s=ServiceHeartbeat.Read(path);if(!ServiceHeartbeat.Fresh(s,now))throw new IOException("Paslaugos signalas nepatvirtintas.");bool freshRun=s.RunId!=lastServiceRun;if(s.RecordedCases>0&&(freshRun||s.RecordedCases>lastServiceCases))Notify("SARGON paslaugos radiniai","Yra išsaugotų radinių įrašų. Atverkite paslaugos būseną ir administratoriaus radinių peržiūrą. Tai nėra pašalinimo patvirtinimas.",ToolTipIcon.Warning);if(s.RealtimeBulkChangeAlertAt>lastServiceBulkNoticeAt){lastServiceBulkNoticeAt=s.RealtimeBulkChangeAlertAt;Notify("SARGON: daug failų pakeitimų","Audito signalas: per trumpą laiką pakeista daug skirtingų failų. Tai nėra viruso patvirtinimas; procesas nenustatytas ir failai automatiškai neblokuojami. Patikrinkite veikiančias programas ir ataskaitą.",ToolTipIcon.Warning);}if((s.State.StartsWith("ERROR",StringComparison.Ordinal)||s.State.StartsWith("STOPPED",StringComparison.Ordinal)||s.State=="DATABASE_UNAVAILABLE_WAITING_UPDATE"||s.State=="ENGINE_READINESS_UNCONFIRMED_WAITING_UPDATE"||s.RealtimeCoverageLost)&&(lastServiceNotice==0||now-lastServiceNotice>TimeSpan.FromMinutes(30).Ticks)){lastServiceNotice=now;Notify("SARGON apsaugos aprėptis nepatvirtinta","Variklio parengtis arba failų pokyčių stebėjimas turi spragų. Atverkite paslaugos būseną ir ataskaitą.",ToolTipIcon.Warning);}lastServiceRun=s.RunId;lastServiceCases=s.RecordedCases;}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException){if(lastServiceNotice==0||now-lastServiceNotice>TimeSpan.FromMinutes(30).Ticks){lastServiceNotice=now;Notify("SARGON paslaugos signalas pasenęs","Paslaugos veikimas nepatvirtintas; vien veikiantis langas nereiškia veikiančios paslaugos.",ToolTipIcon.Warning);}}}
  private void ServiceStatusDialog(){string text;try{long now=DateTime.UtcNow.Ticks;string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"SARGONService","Public","status.json");FolderMonitor.NoLinks(path);var s=ServiceHeartbeat.Read(path);if(!ServiceHeartbeat.Fresh(s,now))throw new IOException("Būsena pasenusi arba nepatvirtinta.");bool probeFresh=s.DatabaseReady&&s.DatabaseProbeAt>0&&s.DatabaseProbeAt<=now&&now-s.DatabaseProbeAt<TimeSpan.FromHours(24).Ticks;text="ATSISKIRTOS PASLAUGOS BŪSENA\r\n"+Data.Clean(s.State)+"\r\nLeidimas: "+s.Version+"; aplankų patikrų: "+s.DirectoryChecks+"; aplankų su radiniais: "+s.Findings+"; spragų: "+s.Unverified+"; istorinių radinių įrašų: "+s.RecordedCases+"; eilėje aplankų: "+s.Pending+"\r\nAtnaujinta: "+new DateTime(s.At,DateTimeKind.Utc).ToLocalTime().ToString("g")+"\r\n\r\nClamAV neutralios DB parengties patikra: "+(probeFresh?new DateTime(s.DatabaseProbeAt,DateTimeKind.Utc).ToLocalTime().ToString("g")+" vietos laiku — praėjo":"nepatvirtinta arba senesnė nei 24 val.")+". Ji įrodo tik tai, kad variklis įkėlė bazes ir perskaitė neutralų failą.\r\nFailų pokyčių stebėjimas: "+(s.RealtimeReady?"veikia pasirinktuose diskuose („po įrašymo“)":"nepatvirtintas / yra spragų")+"; aktyvių šaknų: "+s.RealtimeActiveRoots+"; eilėje: "+s.RealtimePending+"; perskaityta failų: "+s.RealtimeScanned+"; nepatvirtinta: "+s.RealtimeUnverified+"; prarasti įvykiai: "+s.RealtimeDropped+". Aprėptis: "+(s.RealtimeRoots==null?"nežinoma":string.Join(", ",s.RealtimeRoots))+".\r\nMasinių pakeitimų signalas: "+(s.RealtimeBulkChangeAlert?"AKTYVUS — bent ":"neaktyvus — ")+s.RealtimeBulkChangeDistinctPaths+" skirtingų failų stebėtame lange; signalų: "+s.RealtimeBulkChangeBursts+". Tai tik elgsenos perspėjimas: procesas nenustatytas, virusas nepatvirtintas, blokavimas nevykdomas.\r\n\r\nTai veiklos signalas, ne visos sistemos saugumo garantija. Įvykių stebėjimas failą tikrina po pakeitimo; jis neblokuoja vykdymo ir neapima laiko, kai paslauga neveikė. Išsamūs radiniai ir nepatikrintų failų sąrašas paslaugos privačiame žurnale prieinami administratoriui. Paslauga originalų automatiškai nešalina. Konkretų radinį peržiūrėkite meniu „Paslaugos radinių valdymas…“; ten prieš veiksmą jis tikrinamas iš naujo.\r\n\r\nGUI aplanko stebėjimas ir jo DPAPI karantinas yra atskiri nuo paslaugos. Šis langas komandų paslaugai nesiunčia.";}catch(Exception e) when(e is IOException||e is UnauthorizedAccessException||e is ArgumentException||e is InvalidOperationException){text="PASLAUGOS VEIKIMAS NEPATVIRTINTAS\r\nPaslauga neįdiegta, nepasiekiama arba jos signalas pasenęs. Naudokite bendro diegiklio paslaugos ir variklio dalį. Įprasto lango atvėrimas paslaugos neįdiegia.";}
   using(var d=new Form{Text="SARGON paslaugos būsena",Width=790,Height=570,StartPosition=FormStartPosition.CenterParent}){d.Controls.Add(new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=text});ThemeDialog(d);d.ShowDialog(this);}
  }
 }
}
